message.content:
{
  "candidate_edge_types": [
    {
      "name": "ATTEMPTS_TO_REPAIR",
      "definition": "A subsequent agent action attempts to resolve a failure or blocking error identified during an earlier execution step, possibly by substituting a different approach or mechanism rather than fixing the failing component directly.",
      "source_description": "An earlier observed execution failure or blocking error reported by a command or tool.",
      "target_description": "A subsequent agent action intended to work around or resolve that failure."
    },
    {
      "name": "USES_PRIOR_RESULT_AS_INPUT",
      "definition": "An artifact, file path, generated module, or value produced or reported by an earlier execution step is consumed as an input or prerequisite by a subsequent action.",
      "source_description": "A result, artifact, or generated resource produced by an earlier execution step.",
      "target_description": "A subsequent agent action that consumes that result as an input or prerequisite."
    },
    {
      "name": "VERIFIES_PRIOR_RESULT",
      "definition": "A subsequent agent step inspects, measures, or analyzes an artifact or configuration produced by an earlier action in order to confirm that it exists, has the expected content, or is otherwise valid before proceeding.",
      "source_description": "An artifact, output file, or configuration produced by an earlier action.",
      "target_description": "A subsequent inspection or analysis step that confirms the artifact's presence or correctness."
    },
    {
      "name": "MONITORS_LONG_RUNNING_EXECUTION",
      "definition": "After a long-running background process is launched, subsequent events repeatedly observe its output stream to track progress or completion status.",
      "source_description": "A launch event that starts a long-running or asynchronous execution task.",
      "target_description": "A subsequent observation event that reads the task's output to monitor its progress."
    },
    {
      "name": "INVESTIGATES_LACK_OF_PROGRESS",
      "definition": "An observation that a running task has produced no new expected output after an extended period triggers a diagnostic action to confirm the task is still alive or consuming resources.",
      "source_description": "An observation indicating that a running task has not produced the expected new output.",
      "target_description": "A subsequent diagnostic action that checks the task's process status or resource usage."
    }
  ]
}

